import java.util.*;
class NaturalRiverTest{
 static EnvironmentMap map(float[] h){var e=new EnvironmentMap(h.clone());e.water=EnvironmentMap.filled(h.length,62);e.river=new float[h.length];e.material=new byte[h.length];return e;}
 public static void main(String[]args){int n=256;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=180-z*.5f;var flow=EnvironmentNodes.drainage(h,n,()->false);var a=map(h);var b=map(h);var old=map(h);int start=30*n+128;NaturalRivers.trace(a,h,flow,start,n,n,62,3,4,Float.POSITIVE_INFINITY,1.35,913,()->false);NaturalRivers.trace(b,h,flow,start,n,n,62,3,4,Float.POSITIVE_INFINITY,1.35,913,()->false);EnvironmentNodes.trace(old,h,flow,start,n,62,3,4,Float.POSITIVE_INFINITY,()->false);if(!Arrays.equals(a.height,b.height))throw new AssertionError("Not repeatable");int wet=0,off=0,banks=0;for(int i=0;i<h.length;i++){if(a.river[i]>.1){wet++;if(old.river[i]==0)off++;if(a.water[i]>h[i]+1.001)throw new AssertionError("Elevated water column");}else if(a.height[i]<h[i]-.1)banks++;if(h[i]<61&&a.height[i]!=h[i])throw new AssertionError("Ocean cut");}if(wet<100||off<50||banks<100)throw new AssertionError("Missing curves or banks "+wet+" "+off+" "+banks);System.out.println("PASS: curved channels, softened banks, repeatability, ocean preservation and bounded water heights");}
}
